# (key, label, regular expression matched case-insensitively) - the order matters
RULES = [
    ('firewall', 'Firewall',
     r'fire\s?wall|fortigate|palo\s?alto|\bfortinet|\bftg\b|\bngfw\b|\basa\b'),
    ('router', 'Router',
     r'router|routerboard|\bccr\d|\brb\d{3,4}|\bmikrotik\s?ccr|\bgateway\b|\bgw\b|\bbgp\b'),
    ('switch', 'Switch',
     r'switch|\bsw\b|\bcrs\d|\bcss\d|\bpoe\b|\bl2\b|\bl3\b'),
    ('ap', 'Wi-Fi access point',
     r'\bap\b|\baps\b|access[\s_-]?point|wi-?fi|wlan|\bwap\b|\bunifi\b|\bcapsman\b'),
    ('tower', 'Base station / sector',
     r'tower|base[\s_-]?station|\bbts\b|sector|sektor|\bmast\b|\bptmp\b|\bpmp\b|\brm5|\brocket\b|\bsektor'),
    ('antenna', 'Radio link / CPE',
     r'\bptp\b|\bcpe\b|antenna|bridge|radio|wireless|beam|nanostation|airmax|\bltu\b|\blbe\b|\bpb5|\bm5\b|\bm2\b|\bsxt\b|\bqrt\b|\bwap\s?ac\b'),
    ('satellite', 'Satellite',
     r'satellite|\bvsat\b|starlink'),
    ('server', 'Server',
     r'server|\bsrv\b|\bhost\b|\bdns\b|\bdhcp\b|\bvm\b|hypervisor|esxi|proxmox|\bnvr\b|\bradius\b|\bntp\b'),
    ('storage', 'Storage',
     r'\bnas\b|storage|synology|qnap|\bsan\b'),
    ('camera', 'Camera',
     r'camera|cctv|\bcam\b|ip[\s_-]?cam|hikvision|dahua'),
    ('phone', 'VoIP phone / PBX',
     r'phone|voip|\bpbx\b|\bsip\b|asterisk|telephon'),
    ('printer', 'Printer',
     r'printer|\bmfp\b|plotter'),
    ('ups', 'UPS / battery',
     r'\bups\b|battery|inverter|rectifier'),
    ('pdu', 'PDU',
     r'\bpdu\b|power[\s_-]?(strip|distribution)'),
    ('converter', 'Media converter / ONU',
     r'converter|\bonu\b|\bont\b|\bolt\b|gpon|\bsfp\b|\bfib(er|re)\b|\bmc\b|\bmodem\b'),
]

_COMPILED = [(key, re.compile(pattern, re.IGNORECASE)) for key, _label, pattern in RULES]


def icon_for(role='', model='', name=''):
    """The icon key for a device (see the module docstring), or '' when nothing matches."""
    for text in (role, model, name):
        if not text:
            continue
        for key, regex in _COMPILED:
            if regex.search(text):
                return key
    return ''


def graph_icons():
    """The icon set in the form the graph page needs."""
    return {'paths': PATHS, 'rules': [{'key': k, 'label': label, 'pattern': pattern} for k, label, pattern in RULES]}
